descriptor.templateCss:
.trend-card-container.pbd {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 10px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #10B981;
  padding: 12px 18px 10px 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}
.trend-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.trend-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.trend-icon { font-size: 16px; }
.trend-badge {
  font-size: 11px;
  font-weight: 700;
  padding: 2px 10px;
  border-radius: 20px;
  color: #10B981;
  border: 1.5px solid #10B981;
  background: rgba(16, 185, 129, 0.12);
}
.trend-kpi-bar {
  display: flex;
  justify-content: space-around;
  align-items: center;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(100, 184, 86, 0.12);
  border-radius: 8px;
  padding: 5px 12px 6px 12px;
  margin: 6px 0 4px 0;
}
.kpi-col {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.kpi-lbl { font-size: 10px; font-weight: 700; color: #64748b; letter-spacing: 0.5px; }
.kpi-val-group { display: flex; align-items: baseline; gap: 4px; }
.kpi-num { font-size: 19px; font-weight: 800; line-height: 1.1; }
.kpi-unit { font-size: 12px; font-weight: 600; color: #94a3b8; }
.kpi-sub { font-size: 10px; font-weight: 600; color: #94a3b8; margin-top: 1px; letter-spacing: 0.3px; }
.kpi-divider { width: 1px; height: 32px; background: rgba(148, 163, 184, 0.15); }
.chart-wrapper {
  width: 100%;
  flex: 1;
  min-height: 130px;
  position: relative;
}
.trend-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 4px;
  margin-top: 2px;
}

descriptor.controllerScript:
self.onInit = function() {
  self.colors = [
    '#38BDF8', '#10B981', '#F59E0B', '#A855F7',
    '#EC4899', '#14B8A6', '#F97316', '#84CC16',
    '#06B6D4', '#EAB308', '#6366F1', '#22C55E'
  ];
  self.initChart();
  self.setupHoverSync();
  self.onDataUpdated();
};


self.ensureEcharts = function(cb) {
  if (window.echarts) {
    cb();
    return;
  }
  var existing = document.querySelector('script[src*="echarts"]');
  if (!existing) {
    var s = document.createElement('script');
    s.src = '/echarts.min.js';
    s.onload = cb;
    document.head.appendChild(s);
  } else {
    existing.addEventListener('load', cb);
    var attempts = 0;
    var intv = setInterval(function() {
      attempts++;
      if (window.echarts || attempts > 50) {
        clearInterval(intv);
        if (window.echarts) cb();
      }
    }, 100);
  }
};

self.initChart = function() {
  var container = self.ctx.$container ? (self.ctx.$container[0] || self.ctx.$container) : null;
  if (!container) return;
  var el = container.querySelector('#echarts-pbd');
  if (!el) return;

  self.ensureEcharts(function() {
    if (!self.myChart && window.echarts && el.clientWidth > 0 && el.clientHeight > 0) {
      self.myChart = window.echarts.init(el);
      if (self.onResize) self.onResize();
      if (self.onDataUpdated) self.onDataUpdated();
    } else if (!self.myChart && window.echarts) {
      setTimeout(function() {
        if (!self.myChart && el.clientWidth > 0 && el.clientHeight > 0) {
          self.myChart = window.echarts.init(el);
          if (self.onResize) self.onResize();
          if (self.onDataUpdated) self.onDataUpdated();
        }
      }, 200);
    }
  });
};

self.setupHoverSync = function() {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container) return;
  var wrapper = container.querySelector('.chart-wrapper');
  if (wrapper && !self.hasHoverBound) {
    self.hasHoverBound = true;
    wrapper.addEventListener('mouseleave', function() {
      self.restoreDefaultCards();
    });
  }
};

self.onResize = function() {
  if (self.myChart) {
    self.myChart.resize();
  } else {
    self.initChart();
  }
};

self.restoreDefaultCards = function() {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container || !self.cardMetrics) return;

  var m = self.cardMetrics;
  var fmt = function(v) { return (v != null && !isNaN(v) ? Number(v) : 0).toFixed(1); };

  var elSum = container.querySelector('#pbd-sum-val');
  var elSumSub = container.querySelector('#pbd-sum-sub');
  var elAvg = container.querySelector('#pbd-avg-val');
  var elAvgSub = container.querySelector('#pbd-avg-sub');
  var elTop = container.querySelector('#pbd-top-val');
  var elTopSub = container.querySelector('#pbd-top-sub');
  var elBadge = container.querySelector('#pbd-total-badge');

  if (elSum) elSum.textContent = fmt(m.sumVal);
  if (elSumSub) elSumSub.textContent = m.sumSub || 'En Vivo';

  if (elAvg) elAvg.textContent = fmt(m.avgVal);
  if (elAvgSub) elAvgSub.textContent = m.avgSub || '12 Activos';

  if (elTop) elTop.textContent = fmt(m.topVal);
  if (elTopSub) elTopSub.textContent = m.topSub || 'PBD';

  if (elBadge) elBadge.textContent = 'PBD Σ: ' + fmt(m.sumVal) + ' kW';
};

self.onHoverPoint = function(params) {
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (!container || !params || params.length === 0) return;

  var d = new Date(params[0].value[0]);
  var months = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
  var timeStr = months[d.getMonth()] + ' ' + d.getDate() + ' ' + d.toTimeString().split(' ')[0].substring(0, 5);

  var sumH = 0;
  var topH = 0;
  var topName = 'PBD-01';
  var count = 0;

  for (var i = 0; i < params.length; i++) {
    var v = parseFloat(params[i].value[1]) || 0;
    sumH += v;
    count++;
    if (v > topH) {
      topH = v;
      topName = params[i].seriesName;
    }
  }

  var avgH = count > 0 ? sumH / count : 0;
  var fmt = function(v) { return (v != null && !isNaN(v) ? Number(v) : 0).toFixed(1); };

  var elSum = container.querySelector('#pbd-sum-val');
  var elSumSub = container.querySelector('#pbd-sum-sub');
  var elAvg = container.querySelector('#pbd-avg-val');
  var elAvgSub = container.querySelector('#pbd-avg-sub');
  var elTop = container.querySelector('#pbd-top-val');
  var elTopSub = container.querySelector('#pbd-top-sub');

  if (elSum) {
    elSum.textContent = fmt(sumH);
    if (elSumSub) elSumSub.textContent = timeStr;
  }
  if (elAvg) {
    elAvg.textContent = fmt(avgH);
    if (elAvgSub) elAvgSub.textContent = timeStr;
  }
  if (elTop) {
    elTop.textContent = fmt(topH);
    if (elTopSub) elTopSub.textContent = topName;
  }
};

self.smoothSeries = function(pts, targetWindow) {
  if (!pts || pts.length <= 5) return pts;
  var w = targetWindow || 11;
  if (pts.length < 150) w = 3;
  else if (pts.length < 600) w = 7;
  else if (pts.length < 1800) w = 11;
  else w = 15;

  var half = Math.floor(w / 2);
  var res = [];
  for (var i = 0; i < pts.length; i++) {
    var sum = 0, count = 0;
    var start = Math.max(0, i - half);
    var end = Math.min(pts.length - 1, i + half);
    for (var j = start; j <= end; j++) {
      sum += pts[j][1];
      count++;
    }
    res.push([pts[i][0], Math.round((sum / count) * 10) / 10]);
  }
  return res;
};

self.onDataUpdated = function() {
  var data = self.ctx.data || [];
  var pbdMap = {};
  for (var i = 1; i <= 12; i++) {
    var keyNum = i < 10 ? '0' + i : '' + i;
    pbdMap[keyNum] = { pts: [], name: 'PBD-' + keyNum, last: 0, peak: 0 };
  }

  for (var i = 0; i < data.length; i++) {
    var item = data[i];
    var pts = item.data || [];
    var k = (item.dataKey.name || item.dataKey.label || '').toLowerCase();

    // extract pbd number
    var m = k.match(/pbd[_-]?([0-9]{1,2})/);
    if (m) {
      var num = parseInt(m[1], 10);
      var keyNum = num < 10 ? '0' + num : '' + num;
      if (pbdMap[keyNum]) {
        var rawPts = pts.map(function(p) { return [p[0], parseFloat(p[1]) || 0]; });
        rawPts.sort(function(a, b) { return a[0] - b[0]; });
        pbdMap[keyNum].pts = rawPts;
        if (rawPts.length > 0) {
          pbdMap[keyNum].last = rawPts[rawPts.length - 1][1];
          var maxP = 0;
          for (var x = 0; x < rawPts.length; x++) {
            if (rawPts[x][1] > maxP) maxP = rawPts[x][1];
          }
          pbdMap[keyNum].peak = maxP;
        }
      }
    }
  }

  var sumLive = 0;
  var sumPeak = 0;
  var topVal = 0;
  var topName = 'PBD-01';
  var lastVals = [];

  for (var i = 1; i <= 12; i++) {
    var keyNum = i < 10 ? '0' + i : '' + i;
    var info = pbdMap[keyNum];
    sumLive += info.last;
    sumPeak += info.peak;
    lastVals.push(info.last);
    if (info.last > topVal) {
      topVal = info.last;
      topName = info.name;
    }
  }
  var avgLive = sumLive / 12;

  self.cardMetrics = {
    sumVal: sumLive,
    sumSub: 'Pico: ' + sumPeak.toFixed(1) + ' kW',
    avgVal: avgLive,
    avgSub: '12 PBDs en línea',
    topVal: topVal,
    topSub: topName
  };

  self.restoreDefaultCards();

  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var elFooterStats = container.querySelector('#pbd-footer-stats');
    if (elFooterStats) {
      var minP = Math.min.apply(null, lastVals);
      var maxP = Math.max.apply(null, lastVals);
      var deltaP = Math.abs(maxP - minP);
      if (deltaP <= 15) {
        elFooterStats.innerHTML = 'Dispersión: <strong style="color:#64B856;">Equilibrada (ΔP: ' + deltaP.toFixed(1) + ' kW)</strong>';
      } else {
        elFooterStats.innerHTML = 'Dispersión: <strong style="color:#F59E0B;">Desviación PBD (ΔP: ' + deltaP.toFixed(1) + ' kW)</strong>';
      }
    }
  }

  if (!self.myChart) {
    self.initChart();
  }
  if (!self.myChart) return;

  var monthsShort = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
  var seriesList = [];

  for (var i = 1; i <= 12; i++) {
    var keyNum = i < 10 ? '0' + i : '' + i;
    var info = pbdMap[keyNum];
    var clr = self.colors[(i - 1) % self.colors.length];
    var cleanPts = self.smoothSeries(info.pts, 11);

    seriesList.push({
      name: info.name,
      type: 'line',
      data: cleanPts,
      smooth: 0.35,
      showSymbol: false,
      lineStyle: { color: clr, width: 1.6 },
      itemStyle: { color: clr }
    });
  }

  var option = {
    backgroundColor: 'transparent',
    tooltip: {
      trigger: 'axis',
      confine: true,
      alwaysShowContent: false,
      hideDelay: 500,
      extraCssText: 'z-index: 999999; box-shadow: 0 4px 20px rgba(0,0,0,0.7); pointer-events: none; max-height: 280px; overflow-y: auto;',
      backgroundColor: 'rgba(15, 23, 42, 0.95)',
      borderColor: 'rgba(16, 185, 129, 0.4)',
      borderWidth: 1,
      padding: [8, 12],
      textStyle: { color: '#f8fafc', fontSize: 11 },
      axisPointer: {
        type: 'line',
        snap: true,
        lineStyle: { color: 'rgba(255, 255, 255, 0.4)', width: 1.5, type: 'dashed' }
      },
      formatter: function(params) {
        if (!params || params.length === 0) return '';
        self.onHoverPoint(params);
        var d = new Date(params[0].value[0]);
        var timeStr = monthsShort[d.getMonth()] + ' ' + d.getDate() + ', ' + d.toTimeString().split(' ')[0];
        var out = '<div style="font-weight:700; margin-bottom:5px; color:#10B981; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:3px;">✳️ ' + timeStr + '</div>';
        out += '<div style="display:grid; grid-template-columns: 1fr 1fr; gap: 4px 16px;">';
        params.forEach(function(p) {
          out += '<div style="display:flex; justify-content:space-between; gap:8px;">' +
                 '<span>' + p.marker + ' ' + p.seriesName + ':</span>' +
                 '<strong style="color:#ffffff;">' + p.value[1] + ' kW</strong>' +
                 '</div>';
        });
        out += '</div>';
        return out;
      }
    },
    grid: {
      left: 45,
      right: 20,
      top: 15,
      bottom: 28,
      containLabel: false
    },
    dataZoom: [
      {
        type: 'slider',
        show: true,
        bottom: 2,
        height: 18,
        borderColor: 'rgba(16, 185, 129, 0.3)',
        backgroundColor: 'rgba(14, 25, 16, 0.7)',
        fillerColor: 'rgba(16, 185, 129, 0.22)',
        handleStyle: { color: '#10B981', borderColor: '#059669' },
        moveHandleStyle: { color: 'rgba(16, 185, 129, 0.4)' },
        showDetail: true,
        showDataShadow: true,
        dataBackground: {
          lineStyle: { color: '#10B981', width: 1 },
          areaStyle: { color: 'rgba(16, 185, 129, 0.25)' }
        },
        selectedDataBackground: {
          lineStyle: { color: '#38BDF8', width: 1 },
          areaStyle: { color: 'rgba(56, 189, 248, 0.4)' }
        },
        textStyle: { color: '#94a3b8', fontSize: 9 }
      },
      {
        type: 'inside'
      }
    ],
    xAxis: {
      type: 'time',
      axisLine: { lineStyle: { color: 'rgba(100, 184, 86, 0.25)' } },
      axisTick: { show: true, lineStyle: { color: 'rgba(100, 184, 86, 0.25)' } },
      splitLine: { show: false },
      axisLabel: {
        color: '#94a3b8',
        fontSize: 10,
        formatter: function(val) {
          var d = new Date(val);
          var hh = d.getHours();
          var mm = d.getMinutes();
          if (hh === 0 && mm === 0) {
            return '{dayBadge|' + monthsShort[d.getMonth()] + ' ' + d.getDate() + '}';
          }
          return String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
        },
        rich: {
          dayBadge: {
            color: '#ffffff',
            fontWeight: 'bold',
            fontSize: 10,
            backgroundColor: 'rgba(30, 41, 59, 0.9)',
            borderColor: 'rgba(16, 185, 129, 0.5)',
            borderWidth: 1,
            padding: [2, 6],
            borderRadius: 3
          }
        }
      }
    },
    yAxis: {
      type: 'value',
      scale: true,
      min: 0,
      axisLine: { show: false },
      axisLabel: { color: '#94a3b8', fontSize: 10, formatter: '{value} kW' },
      splitLine: { lineStyle: { color: 'rgba(255, 255, 255, 0.05)' } }
    },
    series: seriesList
  };

  self.myChart.setOption(option, true);
};

self.onDestroy = function() {
  if (self.myChart) {
    self.myChart.dispose();
    self.myChart = null;
  }
};
